import hashlib

class RefundBackend:
    def __init__(self):
        self.total_disbursed = 0
        self.idempotency_ledger = {}
        self.network_attempts = 0

    def issue_refund(self, order_id, amount, idempotency_key=None):
        self.network_attempts += 1
        if idempotency_key and idempotency_key in self.idempotency_ledger:
            return self.idempotency_ledger[idempotency_key]

        # Server commits the mutation BEFORE network response travels back!
        self.total_disbursed += amount
        receipt = {"order_id": order_id, "amount": amount, "status": "COMMITTED"}
        if idempotency_key:
            self.idempotency_ledger[idempotency_key] = receipt

        if self.network_attempts == 1:
            raise TimeoutError("504 Gateway Timeout on return path")
        return receipt

# Case 1: Naive agent retries on timeout without idempotency key -> DOUBLE REFUND!
naive_api = RefundBackend()
for _ in range(2):
    try:
        naive_api.issue_refund("ORD-77", 1500)
        break
    except TimeoutError:
        pass

# Case 2: Production agent attaches deterministic session+turn+args idempotency key
safe_api = RefundBackend()
idem_key = hashlib.sha256(b"sess_42|turn_3|ORD-77|1500").hexdigest()[:16]
for _ in range(2):
    try:
        res = safe_api.issue_refund("ORD-77", 1500, idempotency_key=idem_key)
        break
    except TimeoutError:
        pass

assert naive_api.total_disbursed == 3000 and safe_api.total_disbursed == 1500
print(naive_api.total_disbursed, safe_api.total_disbursed, res["status"])

from math import comb

def pass_at_k(n, c, k):
    return 1.0 if n - c < k else 1.0 - comb(n - c, k) / comb(n, k)

# 5 benchmark issues per diagnostic scenario, n = 8 rollouts per issue
scenarios = {
    "case_a_schema": {"c": [2, 1, 2, 1, 2], "schema_err": 0.22},
    "case_b_starved": {"c": [2, 0, 0, 2, 0], "schema_err": 0.02},
    "case_c_sharpen": {"c": [2, 3, 2, 2, 3], "schema_err": 0.03},
}

def diagnose(spec):
    counts = spec["c"]
    p1 = sum(pass_at_k(8, c, 1) for c in counts) / len(counts)
    p8 = sum(pass_at_k(8, c, 8) for c in counts) / len(counts)
    gap = p8 - p1
    if spec["schema_err"] >= 0.15:
        action = "1_Constrained_Decoding_&_Tool_Refactor"
    elif gap < 0.35:
        action = "2_Targeted_SFT_for_Coverage_First"
    else:
        action = "3_GRPO_RLVR_+_TestTime_Sandbox_Filter"
    return round(p1, 2), round(p8, 2), round(gap, 2), action

results = {k: diagnose(v) for k, v in scenarios.items()}
assert results["case_b_starved"][2] == 0.30 and results["case_c_sharpen"][2] == 0.70
for name, res in results.items():
    print(name, res)
